export function legacy2017Pm5Figure(profile:string,values:number[]){if(!legacy2017Pm5Profiles.includes(profile))throw Error('FIGURE_PROFILE');if(!Array.isArray(values)||Object.getOwnPropertyNames(values).sort().join(',')!=='0,length'||Object.getOwnPropertySymbols(values).length)throw Error('FIGURE_DOMAIN');const descriptor=Object.getOwnPropertyDescriptor(values,'0');if(!descriptor||!Object.hasOwn(descriptor,'value')||!Number.isSafeInteger(descriptor.value))throw Error('FIGURE_DOMAIN');const key=profile+':'+descriptor.value,model=legacy2017Pm5Geometry[key];if(!model)throw Error('FIGURE_DOMAIN');const block=legacy2017Pm5Bodies.flatMap(b=>b.prompt).find(b=>b.type==='diagram'&&b.scene.kind==='source_figure'&&b.scene.profile===profile&&b.scene.values[0]===descriptor.value);if(!block||block.type!=='diagram')throw Error('FIGURE_BODY');return{model,alt:block.alt,caption:block.caption};}
